import { configure } from "arktype/config";

// Must be imported BEFORE arktype (and any module that imports arktype)
// so that $ark.config is set before kinds.js freezes resolvedConfig and
// before any type is parsed/compiled with applyConfig.
configure({ numberAllowsNaN: true });

import { type } from "arktype";

// Shared schema used by both index.ts and broken.ts.
// Whether { x: NaN } is accepted depends entirely on whether
// configure({ numberAllowsNaN: true }) was called BEFORE this
// module was first imported (i.e. before this type was compiled).
export const Point = type({ x: "number" });

// ✅ CORRECT ORDER: config is imported first so configure() runs before
// arktype's kinds.js resolves $ark.resolvedConfig and before the Point
// type is compiled by applyConfig.
import "./config.ts";
import { Point } from "./schema.ts";

const result = Point({ x: NaN });

if (result instanceof type.errors) {
  console.error("❌ Unexpected: { x: NaN } was REJECTED:", result.summary);
  process.exit(1);
} else {
  console.log("✅ { x: NaN } accepted (numberAllowsNaN: true is active):", result);
}

// ❌ WRONG ORDER: schema is imported first, which causes arktype to load and
// compile the Point type BEFORE configure() is called.  At parse time,
// applyConfig sees no numberAllowsNaN in $ark.resolvedConfig, so the domain
// node is compiled as a strict "number" check (NaN excluded).
// Calling configure() afterwards is too late for already-compiled types.
import { Point } from "./schema.ts";
import "./config.ts";

const result = Point({ x: NaN });

if (result instanceof type.errors) {
  console.log("✅ Expected: { x: NaN } was REJECTED (config applied too late):", result.summary);
} else {
  console.error("❌ Unexpected: { x: NaN } was accepted – config somehow applied early.");
  process.exit(1);
}

